    description   = EXCLUDED.description,
    updated_at    = now();

-- Verification: three staged rows, and the live row per language
-- unchanged (zh v6, en v4, ja v4).
SELECT language_id, version, is_active, length(template_text) AS len,
       md5(template_text) AS md5
  FROM prompt_templates
 WHERE task_name = 'test_distractor_plausibility'
 ORDER BY language_id, version;
